"""3-seed RSFT 结果汇总：mean±std，对比 SFT baseline。"""

import json
import sys
import os
import numpy as np

SEED_CONFIGS = {
    "r1 (seed=42)": "/root/autodl-tmp/eval_results/rsft_r1/metrics.json",
    "s44 (seed=44)": "/root/autodl-tmp/eval_results/rsft_s44/metrics.json",
    "s43 (seed=43)": "/root/autodl-tmp/eval_results/rsft_s43/metrics.json",
}

S43_FALLBACKS = [
    "/root/autodl-tmp/eval_results/rsft_s43_r2/metrics.json",
]

SFT_BASELINE = {
    "f1": 0.4057,
    "evi_f1": 0.7979,
    "edcr": 0.7118,
}

METRICS = ["f1", "evi_f1", "edcr", "precision", "recall", "pred_count", "n_truncated"]
DISPLAY_NAMES = {
    "f1": "Rel F1",
    "evi_f1": "Evi F1",
    "edcr": "EDCR",
    "precision": "Precision",
    "recall": "Recall",
    "pred_count": "Pred Count",
    "n_truncated": "N Truncated",
}


def load_metrics(path):
    with open(path) as f:
        return json.load(f)


def main():
    results = {}
    missing = []

    for name, path in SEED_CONFIGS.items():
        if os.path.exists(path):
            results[name] = load_metrics(path)
        elif "s43" in name:
            found = False
            for fb in S43_FALLBACKS:
                if os.path.exists(fb):
                    results[name] = load_metrics(fb)
                    print(f"[INFO] {name}: using fallback {fb}")
                    found = True
                    break
            if not found:
                missing.append(name)
                print(f"[WARN] {name}: not found, skipping")
        else:
            missing.append(name)
            print(f"[WARN] {name}: not found, skipping")

    if not results:
        print("[ERROR] No metrics files found.")
        sys.exit(1)

    n_seeds = len(results)
    print(f"\n{'='*72}")
    print(f"  RSFT 3-Seed Summary ({n_seeds}/{len(SEED_CONFIGS)} seeds loaded)")
    print(f"{'='*72}\n")

    # Per-seed table
    header = f"{'Metric':<14}" + "".join(f"{name:>18}" for name in SEED_CONFIGS)
    print(header)
    print("-" * len(header))
    for m in METRICS:
        row = f"{DISPLAY_NAMES[m]:<14}"
        for name in SEED_CONFIGS:
            if name in results:
                v = results[name].get(m, float("nan"))
                if m in ("pred_count", "n_truncated"):
                    row += f"{int(v):>18}"
                else:
                    row += f"{v:>18.4f}"
            else:
                row += f"{'N/A':>18}"
        print(row)

    # Mean ± std
    print(f"\n{'='*72}")
    print(f"  Mean ± Std  (n={n_seeds})    vs  SFT Baseline")
    print(f"{'='*72}\n")

    summary = {}
    header2 = f"{'Metric':<14}{'Mean':>10}{'Std':>10}{'SFT':>10}{'Delta':>10}"
    print(header2)
    print("-" * len(header2))
    for m in METRICS:
        vals = [results[name][m] for name in results if m in results[name]]
        if not vals:
            continue
        arr = np.array(vals, dtype=float)
        mean_v = arr.mean()
        std_v = arr.std(ddof=1) if len(arr) > 1 else 0.0
        sft_v = SFT_BASELINE.get(m)

        summary[m] = {"mean": float(mean_v), "std": float(std_v), "n": len(vals)}
        if sft_v is not None:
            summary[m]["sft"] = sft_v
            summary[m]["delta"] = float(mean_v - sft_v)

        if m in ("pred_count", "n_truncated"):
            delta_str = ""
            sft_str = ""
            if sft_v is not None:
                sft_str = f"{sft_v:>10.0f}"
                delta_str = f"{mean_v - sft_v:>+10.0f}"
            print(f"{DISPLAY_NAMES[m]:<14}{mean_v:>10.1f}{std_v:>10.1f}{sft_str:>10}{delta_str:>10}")
        else:
            delta_str = ""
            sft_str = ""
            if sft_v is not None:
                sft_str = f"{sft_v:>10.4f}"
                delta_str = f"{mean_v - sft_v:>+10.4f}"
            print(f"{DISPLAY_NAMES[m]:<14}{mean_v:>10.4f}{std_v:>10.4f}{sft_str}{delta_str}")

    # Save JSON
    output = {
        "n_seeds": n_seeds,
        "missing": missing,
        "per_seed": {name: {m: results[name].get(m) for m in METRICS} for name in results},
        "summary": summary,
        "sft_baseline": SFT_BASELINE,
    }
    out_path = "/root/autodl-tmp/eval_results/3seed_summary.json"
    with open(out_path, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\n[SAVED] {out_path}")


if __name__ == "__main__":
    main()
